+template<template<class> class Field, class Type>
+Type max(const FieldField<Field, Type>& f)
+{
+    label i = 0;
+    while (i < f.size() && !f[i].size()) i++;
+
+    if (i < f.size())
+    {
+        Type Max(max(f[i].field()));
+
+        for (label j=i+1; j<f.size(); j++)
+        {
+            if (f[j].size())
+            {
+                Max = max(max(f[j].field()), Max);
+            }
+        }
+
+        return Max;
+    }
+    else
+    {
+        return pTraits<Type>::min;
+    }
+}
+
+TMP_UNARY_FUNCTION(Type, max)
+
+template<template<class> class Field, class Type>
+Type min(const FieldField<Field, Type>& f)
+{
+    label i = 0;
+    while (i < f.size() && !f[i].size()) i++;
+
+    if (i < f.size())
+    {
+        label i = 0;
+        while (!f[i].size()) i++;
+
+        Type Min(min(f[i].field()));
+
+        for (label j=i+1; j<f.size(); j++)
+        {
+            if (f[j].size())
+            {
+                Min = min(min(f[j].field()), Min);
+            }
+        }
+
+        return Min;
+    }
+    else
+    {
+        return pTraits<Type>::max;
+    }
+}
+
+TMP_UNARY_FUNCTION(Type, min)
