+template<template<class> class Field, class Type>
+Type sum(const FieldField<Field, Type>& f)
+{
+    if (f.size())
+    {
+        Type Sum = Zero;
+
+        forAll(f, i)
+        {
+            Sum += sum(f[i]);
+        }
+
+        return Sum;
+    }
+    else
+    {
+        return Zero;
+    }
+}
