+        CompletionType::Filename
+    }
+
+    fn update(&self, v: FlagValue, args: &mut LowArgs) -> anyhow::Result<()> {
+        check_indexing_allowed()?;
+        args.index_path = Some(PathBuf::from(v.unwrap_value()));
+        Ok(())
+    }
+}
